import { inject } from 'vue'
import { APP_CONFIG_KEY, type AppConfig } from '@@vyui:lib/types'
import icons from '@@vyui:theme/icons'

/**
 * Fallback config used when components are rendered outside a `VyUI` app
 * context (storybook, isolated tests). Keeps the icon registry intact so
 * `useComponentIcons` still resolves semantic names.
 */
const FALLBACK_CONFIG: AppConfig = {
  ui: {
    icons,
    primary: 'green',
    gray: 'slate',
  },
}

/** Inject the merged `AppConfig` provided by `VyUI.install()`. */
export const useAppConfig = (): AppConfig => inject(APP_CONFIG_KEY, FALLBACK_CONFIG)

import { computed, type ComputedRef, type MaybeRefOrGetter, toValue } from 'vue'
import { tv, type TVReturnType, type VariantProps } from 'tailwind-variants'
import { resolveColors } from '@@vyui:theme/colors'
import { useAppConfig } from '@@vyui:composables/useAppConfig'

/**
 * The factory returned by calling `tv(theme)`. Calling it with variant props
 * yields the slot map (or class string for slotless themes).
 */
export type TVFactory = ReturnType<typeof tv>

/**
 * The invoked result of a `tv` factory — either a slot map (object of slot
 * fns) or a flat class string. The component-side type is generally the
 * intersection of those two (`string & { [slot]: ... }`), which is how
 * tailwind-variants types the call without picking a branch.
 *
 * TODO(types): the upstream `TV` is an interface (not a generic function),
 * so we can't thread `TTheme` into the slot-key list. Component templates
 * still get the right shape because Volar resolves `ui.value.<slot>` against
 * the actual `tv(theme)` factory after type narrowing — this `any` only
 * shows up if a caller pulls `useStyledComponent` apart and re-types it.
 */
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export type TVInvoked = any

/**
 * Resolve a theme to its concrete `tv` config. Theme default exports are now
 * **builder functions** `(colors: string[]) => themeObject` so the configurable
 * color list (`appConfig.ui.colors`) threads into the emitted variants. Legacy
 * plain-object themes are passed through unchanged.
 */
export type ResolveTheme<T> = T extends (...args: never[]) => infer R ? R : T

/**
 * Build a per-app-config `tv` factory for a styled component. Merges the
 * package default theme with any user override at `appConfig.ui[name]` and
 * returns the invoked slot map (under `ui`).
 *
 * Accepts either a builder theme (`(colors) => themeObject`, invoked with the
 * resolved color list) or a plain theme object (used as-is). Builder detection
 * happens inside the `computed`, so themes track `appConfig.ui.colors`
 * reactively.
 *
 * Type-wise: the factory return type is `ReturnType<typeof tv>` — same as
 * what the hand-written `buildXxx` helpers produced. That keeps the
 * `VariantProps<ReturnType<typeof tv>>` shape that components use to derive
 * their public variant prop types working without change.
 *
 * @param name      Key under `appConfig.ui` where user overrides live (e.g.
 *                  `'button'`, `'switch'`).
 * @param theme     The package default theme — a builder function or a plain
 *                  `tv` config object.
 * @param variants  Variant props for the component. Accepts a ref, getter, or
 *                  plain object; re-evaluated on every change.
 */
export function useStyledComponent<TTheme>(
  name: string,
  theme: TTheme,
  variants: MaybeRefOrGetter<Record<string, unknown>>,
): {
  ui: ComputedRef<TVInvoked>
} {
  const appConfig = useAppConfig()
  const tvFactory = computed(() => {
    // Factories are memoized on (appConfig, name): the config object is stable
    // per app and not reactive, so per-instance rebuilds bought nothing and
    // cost real time on Lynx's interpreter.
    let perApp = factoryCache.get(appConfig)
    if (!perApp) {
      perApp = new Map()
      factoryCache.set(appConfig, perApp)
    }
    const cached = perApp.get(name)
    if (cached)
      return cached

    // Builder themes are invoked with the resolved color list
    // (`appConfig.ui.colors`); plain-object themes pass through.
    const base = typeof theme === 'function'
      ? (theme as (colors: string[]) => unknown)(resolveColors(appConfig))
      : theme
    const overrides = (appConfig.ui as Record<string, unknown>)[name] as Record<string, unknown> | undefined
    // `extend: tv(base)` lets app-level overrides win on a key-by-key basis
    // while still inheriting everything from the package default. Cast through
    // `unknown` because `tv`'s parameter type is an overloaded generic that
    // doesn't match a `TTheme` constraint cleanly — see TODO above.
    const factory = tv({ extend: tv(base as never), ...(overrides || {}) } as never) as unknown as TVFactory
    perApp.set(name, factory)
    return factory
  })
  const ui = computed(() => tvFactory.value(toValue(variants) as Parameters<TVFactory>[0]))
  return { ui }
}

/** Built `tv` factories per app config, keyed by component theme name. */
const factoryCache = new WeakMap<object, Map<string, TVFactory>>()

/**
 * Type-only helper for deriving the `tv` factory return type from a theme
 * object. `tv` is an overloaded interface (not a generic function), so
 * `ReturnType<typeof tv<typeof theme>>` doesn't work directly. We instead
 * project the theme's `slots` / `variants` shape into `TVReturnType` ourselves,
 * which is what `tv` itself returns at runtime.
 *
 * Usage in a component `<script lang="ts">`:
 *
 *   import theme from '../theme/button'
 *   import type { ThemeTV, VariantProps } from '../composables/useStyledComponent'
 *   type ButtonTV = ThemeTV<typeof theme>
 *   type ButtonVariants = VariantProps<ButtonTV>
 *
 * Equivalent to the old `VariantProps<ReturnType<typeof buildButton>>` chain
 * but with no per-component factory function in the public surface.
 */
// `TVReturnType` projects the theme's `variants` directly into the call
// signature returned to consumers, so `VariantProps<>` can introspect it via
// `Parameters[0]`. The `any`s for the other type params (`B`/`C`/`EV`/`ES`)
// are intentional — none of them affect the variant key shape that the
// component public API depends on.
//
// eslint-disable @typescript-eslint/no-explicit-any
// `ResolveTheme<TTheme>` unwraps builder themes (`(colors) => themeObject`) to
// their config object first, so `ThemeTV<typeof theme>` keeps working unchanged
// for both builder and plain-object themes — zero component-side changes.
export type ThemeTV<TTheme, R = ResolveTheme<TTheme>> = TVReturnType<
  // Variants — extracted from the (resolved) theme.
  R extends { variants: infer V } ? (V extends Record<string, any> ? V : any) : any,
  // Slots — extracted from the (resolved) theme.
  R extends { slots: infer S } ? (S extends Record<string, any> ? S : any) : any,
  // B (base) stays `any`; the rest must NOT be `any`. `TVProps` branches on the
  // extend-variants param — `any` there widens every variant key to
  // `PropertyKey` (losing the literal `color` union). `{}` for config/extend
  // variants and `undefined` for extend slots/extend take the clean branch so
  // `VariantProps<ThemeTV<…>>` recovers the exact variant unions.
  any, {}, {}, undefined, undefined
>

export type { VariantProps }

import { computed, toValue, type MaybeRefOrGetter } from 'vue'
import { useAppConfig } from '@@vyui:composables/useAppConfig'

// Ported from nuxt/ui v3.0.2 `src/runtime/composables/useComponentIcons.ts`.
// The `avatar` prop is left loosely typed as `unknown` here to avoid a hard
// dependency on `Avatar`'s props.

export interface UseComponentIconsProps {
  /**
   * Display an icon based on the `leading` and `trailing` props.
   * @IconifyIcon
   */
  icon?: string
  /** Display an avatar on the left side. */
  avatar?: unknown
  /** When `true`, the icon will be displayed on the left side. */
  leading?: boolean
  /**
   * Display an icon on the left side.
   * @IconifyIcon
   */
  leadingIcon?: string
  /** When `true`, the icon will be displayed on the right side. */
  trailing?: boolean
  /**
   * Display an icon on the right side.
   * @IconifyIcon
   */
  trailingIcon?: string
  /** When `true`, the loading icon will be displayed. */
  loading?: boolean
  /**
   * The icon when the `loading` prop is `true`.
   * @defaultValue appConfig.ui.icons.loading
   * @IconifyIcon
   */
  loadingIcon?: string
}

export function useComponentIcons(componentProps: MaybeRefOrGetter<UseComponentIconsProps>) {
  const appConfig = useAppConfig()

  const props = computed(() => toValue(componentProps))

  const isLeading = computed(() => (props.value.icon && props.value.leading) || (props.value.icon && !props.value.trailing) || (props.value.loading && !props.value.trailing) || !!props.value.leadingIcon)
  const isTrailing = computed(() => (props.value.icon && props.value.trailing) || (props.value.loading && props.value.trailing) || !!props.value.trailingIcon)

  const leadingIconName = computed(() => {
    if (props.value.loading) {
      return props.value.loadingIcon || appConfig.ui.icons?.loading
    }

    return props.value.leadingIcon || props.value.icon
  })
  const trailingIconName = computed(() => {
    if (props.value.loading && !isLeading.value) {
      return props.value.loadingIcon || appConfig.ui.icons?.loading
    }

    return props.value.trailingIcon || props.value.icon
  })

  return {
    isLeading,
    isTrailing,
    leadingIconName,
    trailingIconName,
  }
}

// Explicit `.js` — `tailwindcss/colors` has no `exports` map, so the
// extensionless specifier resolves under bundlers but throws under Node's pure
// ESM resolver (which the packed-tarball smoke test uses). The `.js` form works
// everywhere.
import twColors from 'tailwindcss/colors.js'
import type { AppConfig } from '@@vyui:lib/types'
import { SEMANTIC_TO_PALETTE_DEFAULT } from '@@vyui:theme/color-constants'

const FALLBACK_HEX = '#64748b' // slate-500

/**
 * Resolve a semantic color (`primary`, `error`, …) plus shade to a literal
 * hex string. Used to color Lynx `<svg>` icons — Lynx's SVG element
 * rasterizes the XML and can't inherit `currentColor`, so the fill has to
 * be baked at render time. Tailwind classes (`text-error-500`) still apply
 * to non-SVG slots; this util is for the icon's `:color` prop.
 *
 * Resolution order:
 *  1. `appConfig.ui[semantic]` (e.g. `appConfig.ui.primary === 'rose'`)
 *  2. `appConfig.ui.gray` when semantic is `neutral`
 *  3. The default palette mapping (matches the package's CSS vars)
 */
export function resolveColorHex(
  appConfig: AppConfig,
  semantic: string | undefined,
  shade: number | string = 500,
): string {
  const name = semantic || 'primary'

  const ui = appConfig.ui as Record<string, unknown>
  let palette = typeof ui[name] === 'string' ? (ui[name] as string) : undefined
  if (!palette && name === 'neutral' && typeof ui.gray === 'string') palette = ui.gray as string
  if (!palette) palette = SEMANTIC_TO_PALETTE_DEFAULT[name] ?? 'slate'

  const scale = (twColors as unknown as Record<string, Record<string, string> | string>)[palette]
  // `black` / `white` are single strings in `tailwindcss/colors`, not 11-shade
  // scales — they have no shade to index, so every shade resolves to the one
  // value. Without this a monochrome accent silently fell back to slate-500 for
  // baked SVG fills while its Tailwind classes painted black.
  if (typeof scale === 'string') return scale
  return scale?.[String(shade)] ?? FALLBACK_HEX
}

import type { Component, InjectionKey } from 'vue'

/** Recursive `Partial<T>` — every nested property is also optional. */
export type DeepPartial<T> = {
  [K in keyof T]?: T[K] extends object ? DeepPartial<T[K]> : T[K]
}

/**
 * Per-component theme override bucket. Keyed by component name (e.g. `button`,
 * `input`). Each entry is a partial of the component's resolved
 * `tailwind-variants` config. Typed as `Record<string, unknown>` here because
 * component themes register themselves lazily — strong typing happens at each
 * component boundary via `Partial<typeof theme>`.
 */
export type ComponentThemes = Record<string, unknown>

export interface AppConfig {
  ui: {
    /** Semantic primary color name (maps to a tailwind palette via CSS vars). */
    primary?: string
    /** Semantic gray/neutral color name. */
    gray?: string
    /** List of semantic color names exposed to component `color` variants. */
    colors?: string[]
    /** Semantic icon name → Iconify id (e.g. `loading` → `i-lucide-loader-circle`). */
    icons?: Record<string, string>
  } & ComponentThemes
}

export const APP_CONFIG_KEY: InjectionKey<AppConfig> = Symbol('vyui:app-config')

export interface VyUIPluginOptions {
  /** Override the default `ui` config — deep-merged over the package defaults. */
  ui?: DeepPartial<AppConfig['ui']>
  /**
   * Register only this subset of components globally (keyed by tag name, e.g.
   * `{ VyButton, VyModal }`). Defaults to the full `REGISTRY`. Passing an
   * explicit set lets the bundler tree-shake the components you don't list.
   */
  components?: Record<string, Component>
}

import type { App, Plugin } from 'vue'
import { defu } from 'defu'
import { APP_CONFIG_KEY, type AppConfig, type VyUIPluginOptions } from '@@vyui:lib/types'
import icons from '@@vyui:theme/icons'

const styleDefaults = {
  "primary": "green"
}

/**
 * Package-level defaults; user options are deep-merged on top via `defu`.
 * Per-component theme overrides baked in here are picked up by each component
 * via `appConfig.ui[name]` → `tv({ extend: tv(base), ...overrides })`.
 */
const defaultConfig: AppConfig = {
  ui: { icons, gray: '__VYUI_GRAY__', ...styleDefaults },
}

/**
 * Vue plugin. Provides the merged `AppConfig` consumed by `useAppConfig`.
 * Register it once with your lib alias, e.g.
 * `createApp(App).use(VyUI, { ui: { primary: 'blue' } })`.
 */
export const VyUI: Plugin<VyUIPluginOptions> = {
  install(app: App, options: VyUIPluginOptions = {}) {
    const merged = defu({ ui: options.ui ?? {} }, defaultConfig) as AppConfig
    app.provide(APP_CONFIG_KEY, merged)
  },
}

/*
 * @vyui/kit default theme tokens.
 *
 * Three tiers (mirrors the Nuxt UI semantic-color pattern, ported to Tailwind 3):
 *   1. Palette:  `--ui-color-{semantic}-{shade}` maps a semantic color to a
 *      concrete Tailwind palette via `theme()`.
 *   2. Mode:     `--ui-{semantic}` picks a single shade per mode (-500 light,
 *      -400 dark). Used by shorthand utilities like `bg-primary` / `text-error`.
 *   3. Semantic: role-based `--ui-text*` / `--ui-bg*` / `--ui-border*` tokens
 *      (exposed as `text-muted`, `bg-elevated`, `border-default`, …) that FLIP
 *      between modes on their own — see the DARK MODE banner.
 *
 * Default semantic → palette mapping (tuned for chroma at -500):
 *   primary → green, secondary → blue, success → emerald, info → sky,
 *   warning → amber, error → red, neutral → slate.
 * Tailwind's `yellow` / base `blue` / base `green` are too washed at -500;
 * amber / sky / emerald carry better contrast on white.
 *
 * Override any of these in a downstream CSS file to rebrand without touching
 * @vyui/kit code.
 *
 * ── DARK MODE ──────────────────────────────────────────────────────────────
 * The library flips via SEMANTIC TOKENS, the nuxt/ui + shadcn convention: every
 * theme (and every consumer) writes role-based classes — `text-highlighted`
 * (headings), `text-muted` (captions), `bg-default` (surfaces), `bg-elevated`
 * (raised fills), `border-default` — NEVER a raw `text-neutral-900`. A single
 * `.dark` class on an app-root ancestor (see `useColorMode`) redefines those
 * tokens to their dark values, so the whole tree re-skins with ZERO `dark:`
 * variants and no per-element work.
 *
 * Contract, in two halves:
 *   • The tokens FLIP. `--ui-text-muted` is `slate-500` in `:root`, `slate-400`
 *     in `.dark`; `--ui-bg` is `white` → `slate-900`; and so on. Use them for
 *     anything mode-sensitive.
 *   • The RAMP does NOT. `--ui-color-neutral-*` is a FIXED slate scale in both
 *     modes — a raw `bg-neutral-100` is the same shade light or dark. This is
 *     deliberate (least surprise): raw ramp = a literal shade you picked; tokens
 *     = the thing that adapts. Only the accent RAMPS' mode tier shifts (-500 →
 *     -400) so `bg-primary` shorthands keep contrast on dark surfaces.
 *
 * Rule: token values are `theme()` LITERALS, never `var(--ui-color-*)` refs —
 * Lynx native resolves only ONE level of var() indirection, so a token holding a
 * var() ref collapses on device. Rebrand the neutral base once via `baseColor`
 * (the grayify build step rewrites the `slate` literals — ramp AND tokens — to
 * the chosen gray), or override individual `--ui-*` tokens per mode downstream.
 *
 * ── SYNC CONTRACT ──────────────────────────────────────────────────────────
 * This file ships RAW (never compiled) so it CANNOT import the shared color
 * source of truth (`src/theme/color-constants.js`). It must be hand-kept in
 * sync: there is one `--ui-color-{semantic}-{50..950}` block per color in
 * `ALL_COLORS`, and each block's palette must match
 * `SEMANTIC_TO_PALETTE_DEFAULT` in color-constants.js. Adding a custom color
 * (e.g. `tertiary`) requires adding its block here by hand (the consumer
 * override contract — same as nuxt/ui's CSS-var requirement).
 */
:root {
  /* primary */
  --ui-color-primary-50:  theme('colors.green.50');
  --ui-color-primary-100: theme('colors.green.100');
  --ui-color-primary-200: theme('colors.green.200');
  --ui-color-primary-300: theme('colors.green.300');
  --ui-color-primary-400: theme('colors.green.400');
  --ui-color-primary-500: theme('colors.green.500');
  --ui-color-primary-600: theme('colors.green.600');
  --ui-color-primary-700: theme('colors.green.700');
  --ui-color-primary-800: theme('colors.green.800');
  --ui-color-primary-900: theme('colors.green.900');
  --ui-color-primary-950: theme('colors.green.950');

  /* secondary */
  --ui-color-secondary-50:  theme('colors.blue.50');
  --ui-color-secondary-100: theme('colors.blue.100');
  --ui-color-secondary-200: theme('colors.blue.200');
  --ui-color-secondary-300: theme('colors.blue.300');
  --ui-color-secondary-400: theme('colors.blue.400');
  --ui-color-secondary-500: theme('colors.blue.500');
  --ui-color-secondary-600: theme('colors.blue.600');
  --ui-color-secondary-700: theme('colors.blue.700');
  --ui-color-secondary-800: theme('colors.blue.800');
  --ui-color-secondary-900: theme('colors.blue.900');
  --ui-color-secondary-950: theme('colors.blue.950');

  /* success */
  --ui-color-success-50:  theme('colors.emerald.50');
  --ui-color-success-100: theme('colors.emerald.100');
  --ui-color-success-200: theme('colors.emerald.200');
  --ui-color-success-300: theme('colors.emerald.300');
  --ui-color-success-400: theme('colors.emerald.400');
  --ui-color-success-500: theme('colors.emerald.500');
  --ui-color-success-600: theme('colors.emerald.600');
  --ui-color-success-700: theme('colors.emerald.700');
  --ui-color-success-800: theme('colors.emerald.800');
  --ui-color-success-900: theme('colors.emerald.900');
  --ui-color-success-950: theme('colors.emerald.950');

  /* info */
  --ui-color-info-50:  theme('colors.sky.50');
  --ui-color-info-100: theme('colors.sky.100');
  --ui-color-info-200: theme('colors.sky.200');
  --ui-color-info-300: theme('colors.sky.300');
  --ui-color-info-400: theme('colors.sky.400');
  --ui-color-info-500: theme('colors.sky.500');
  --ui-color-info-600: theme('colors.sky.600');
  --ui-color-info-700: theme('colors.sky.700');
  --ui-color-info-800: theme('colors.sky.800');
  --ui-color-info-900: theme('colors.sky.900');
  --ui-color-info-950: theme('colors.sky.950');

  /* warning */
  --ui-color-warning-50:  theme('colors.amber.50');
  --ui-color-warning-100: theme('colors.amber.100');
  --ui-color-warning-200: theme('colors.amber.200');
  --ui-color-warning-300: theme('colors.amber.300');
  --ui-color-warning-400: theme('colors.amber.400');
  --ui-color-warning-500: theme('colors.amber.500');
  --ui-color-warning-600: theme('colors.amber.600');
  --ui-color-warning-700: theme('colors.amber.700');
  --ui-color-warning-800: theme('colors.amber.800');
  --ui-color-warning-900: theme('colors.amber.900');
  --ui-color-warning-950: theme('colors.amber.950');

  /* error */
  --ui-color-error-50:  theme('colors.red.50');
  --ui-color-error-100: theme('colors.red.100');
  --ui-color-error-200: theme('colors.red.200');
  --ui-color-error-300: theme('colors.red.300');
  --ui-color-error-400: theme('colors.red.400');
  --ui-color-error-500: theme('colors.red.500');
  --ui-color-error-600: theme('colors.red.600');
  --ui-color-error-700: theme('colors.red.700');
  --ui-color-error-800: theme('colors.red.800');
  --ui-color-error-900: theme('colors.red.900');
  --ui-color-error-950: theme('colors.red.950');

  /* neutral — a FIXED slate scale (does not invert; see the DARK MODE banner) */
  --ui-color-neutral-50:  theme('colors.__VYUI_GRAY__.50');
  --ui-color-neutral-100: theme('colors.__VYUI_GRAY__.100');
  --ui-color-neutral-200: theme('colors.__VYUI_GRAY__.200');
  --ui-color-neutral-300: theme('colors.__VYUI_GRAY__.300');
  --ui-color-neutral-400: theme('colors.__VYUI_GRAY__.400');
  --ui-color-neutral-500: theme('colors.__VYUI_GRAY__.500');
  --ui-color-neutral-600: theme('colors.__VYUI_GRAY__.600');
  --ui-color-neutral-700: theme('colors.__VYUI_GRAY__.700');
  --ui-color-neutral-800: theme('colors.__VYUI_GRAY__.800');
  --ui-color-neutral-900: theme('colors.__VYUI_GRAY__.900');
  --ui-color-neutral-950: theme('colors.__VYUI_GRAY__.950');

  /*
   * Mode tier — picks the active shade for shorthand utilities (`bg-primary`).
   * Holds `theme()` LITERALS, not `var(--ui-color-*-500)` refs: `bg-primary`
   * resolves `var(--ui-primary)` (one hop) and Lynx native stops after one hop,
   * so a nested var() ref here would collapse on device. To rebrand the mode
   * tier, override these directly (overriding the `--ui-color-*` ramp no longer
   * flows through). The heavily-used ramp utilities (`bg-primary-500`) resolve
   * the ramp in one hop and still honor `--ui-color-*` overrides.
   */
  --ui-primary:   theme('colors.green.500');
  --ui-secondary: theme('colors.blue.500');
  --ui-success:   theme('colors.emerald.500');
  --ui-info:      theme('colors.sky.500');
  --ui-warning:   theme('colors.amber.500');
  --ui-error:     theme('colors.red.500');

  /*
   * ── SEMANTIC TOKENS (mode-aware; flip in `.dark`) ──────────────────────────
   * Role-based aliases every theme + consumer uses INSTEAD of raw ramp classes,
   * so app chrome flips for free with zero `dark:`. `theme()` LITERALS only
   * (single-level var() rule) — redefined concretely in `.dark` below.
   */

  /* Text — foreground tiers, dim → strong. `text-default` = `var(--ui-text)`. */
  --ui-text-dimmed:      theme('colors.__VYUI_GRAY__.400');
  --ui-text-muted:       theme('colors.__VYUI_GRAY__.500');
  --ui-text-toned:       theme('colors.__VYUI_GRAY__.600');
  --ui-text:             theme('colors.__VYUI_GRAY__.700');
  --ui-text-highlighted: theme('colors.__VYUI_GRAY__.900');
  /* High-contrast foreground for `bg-inverted` fills (paired). */
  --ui-text-inverted:    theme('colors.white');

  /*
   * Background — base surface (white) + fill tints (gray), light → strong.
   * `bg-default` is the surface for cards, fields and overlays; `bg-muted` /
   * `bg-elevated` / `bg-accented` are progressively stronger fills for soft /
   * subtle variants and interactive (active/open) states. `bg-inverted` is the
   * high-contrast fill for neutral `solid` surfaces (button/card).
   */
  --ui-bg:          theme('colors.white');
  --ui-bg-muted:    theme('colors.__VYUI_GRAY__.50');
  --ui-bg-elevated: theme('colors.__VYUI_GRAY__.100');
  --ui-bg-accented: theme('colors.__VYUI_GRAY__.200');
  --ui-bg-inverted: theme('colors.__VYUI_GRAY__.900');

  /* Border. `border-default` = `var(--ui-border)`. */
  --ui-border:          theme('colors.__VYUI_GRAY__.200');
  --ui-border-muted:    theme('colors.__VYUI_GRAY__.100');
  --ui-border-accented: theme('colors.__VYUI_GRAY__.300');
  --ui-border-inverted: theme('colors.__VYUI_GRAY__.900');

  /*
   * Border-radius base. Every `rounded-*` utility resolves to a multiple of
   * this single var (see `tailwind.js`), so overriding it once rescales every
   * component. Recommended steps:
   *   0      → square
   *   0.125  → tight
   *   0.25   → default (matches Tailwind's stock `rounded`)
   *   0.375  → soft
   *   0.5    → pillowy
   */
  --ui-radius: 0.25rem;
}

/*
 * Dark tokens. See the DARK MODE banner. Only the mode tier + semantic tokens
 * are redefined; the neutral ramp stays FIXED (raw `neutral-*` classes do not
 * flip), and the accent ramps inherit `:root`. Values are `theme()` literals
 * (single-level var() rule). Applied via a `.dark` class on an app-root
 * ancestor (`useColorMode`); custom-property inheritance flows to descendants.
 */
.dark {
  /* Mode tier — one notch brighter (-400) for legibility on dark surfaces. */
  --ui-primary:   theme('colors.green.400');
  --ui-secondary: theme('colors.blue.400');
  --ui-success:   theme('colors.emerald.400');
  --ui-info:      theme('colors.sky.400');
  --ui-warning:   theme('colors.amber.400');
  --ui-error:     theme('colors.red.400');

  /* Text — designed dark values (not a mechanical ramp flip). */
  --ui-text-dimmed:      theme('colors.__VYUI_GRAY__.500');
  --ui-text-muted:       theme('colors.__VYUI_GRAY__.400');
  --ui-text-toned:       theme('colors.__VYUI_GRAY__.300');
  --ui-text:             theme('colors.__VYUI_GRAY__.200');
  --ui-text-highlighted: theme('colors.white');
  --ui-text-inverted:    theme('colors.__VYUI_GRAY__.900');

  /* Background — surfaces recede to slate-900; fills lift a notch off it. */
  --ui-bg:          theme('colors.__VYUI_GRAY__.900');
  --ui-bg-muted:    theme('colors.__VYUI_GRAY__.800');
  --ui-bg-elevated: theme('colors.__VYUI_GRAY__.800');
  --ui-bg-accented: theme('colors.__VYUI_GRAY__.700');
  --ui-bg-inverted: theme('colors.white');

  /* Border. */
  --ui-border:          theme('colors.__VYUI_GRAY__.800');
  --ui-border-muted:    theme('colors.__VYUI_GRAY__.800');
  --ui-border-accented: theme('colors.__VYUI_GRAY__.700');
  --ui-border-inverted: theme('colors.white');
}

/*
 * ── Modal (Dialog) open/close motion ───────────────────────────────────────
 * @vyui/core is headless — it ships no animation, only the Presence lifecycle
 * hook classes (`ui-entering` / `ui-leaving` / `ui-open` / `ui-closed`) on the
 * backdrop + panel. `VyModal`'s theme tags those elements with the
 * `vy-modal-overlay` / `vy-modal-content` markers (the `transition` variant);
 * the choreography lives here.
 *
 * Why lifecycle classes and not `data-[state]`: Presence mounts the surface ~8
 * frames before it flips to `Entering`. The base rule below keeps it at
 * `opacity: 0` through that mount→enter gap, so the dim never paints
 * full-opacity before the fade-in (the long-standing first-open flash). And
 * `ui-leaving` fires the exit ONLY on a real close — `data-[state=closed]`
 * can't tell "freshly mounted, closed" from "closing", so it would wrongly run
 * the exit animation on open.
 *
 * Keyframes (`vyui-fade-*` / `vyui-zoom-*`) ship from `@vyui/core`'s
 * `presence.css`. `both` fill-mode holds the start state before and the end
 * state after each run.
 */
.vy-modal-overlay { opacity: 0; }
.vy-modal-overlay.ui-open { opacity: 1; }
.vy-modal-overlay.ui-entering { animation: vyui-fade-in 250ms ease-out both; }
.vy-modal-overlay.ui-leaving  { animation: vyui-fade-out 200ms ease-in both; }

.vy-modal-content { opacity: 0; }
.vy-modal-content.ui-open { opacity: 1; }
.vy-modal-content.ui-entering { animation: vyui-zoom-in 250ms ease-out both; }
.vy-modal-content.ui-leaving  { animation: vyui-zoom-out 200ms ease-in both; }

/**
 * @vyui/kit Tailwind preset.
 *
 * Wires the semantic color names used by every theme file (`bg-primary-500`,
 * `text-error-50`, etc.) to the CSS variables defined in `style.css`. Also
 * safelists the EXACT classes the themes emit for the configured color set
 * (collected by walking the packaged tv configs) — the themes build them via
 * template literals, which Tailwind's static scanner cannot see.
 *
 * Plain `.js` (CJS-compatible) so Tailwind's jiti-based config loader can
 * import it through package `exports` on any Node version. The color list is
 * shared with the TS/runtime plane via `./theme/color-constants.js` (the single
 * source of truth).
 *
 * Usage (default color set):
 * ```ts
 * import vyuiPreset from '@vyui/kit/tailwind'
 * export default {
 *   content: [...],
 *   presets: [lynxPreset, vyuiPreset],
 * }
 * ```
 *
 * Usage (custom color set — must mirror `appConfig.ui.colors`):
 * ```ts
 * import { createVyuiPreset } from '@vyui/kit/tailwind'
 * export default {
 *   presets: [lynxPreset, createVyuiPreset({ colors: [...COLORS, 'tertiary'] })],
 * }
 * ```
 *
 * @typedef {import('tailwindcss').Config} TailwindConfig
 */

import { COLORS, NEUTRAL, SHADES } from './theme/color-constants.js'
// Explicit `.ts` so the source plane resolves under jiti (the example apps'
// tailwind configs import `src/tailwind.js` directly, and jiti's CJS resolver
// won't remap `.js` → `.ts`). Vite rewrites this to `./theme/index.js` in dist.
import * as themeExports from './theme/index.ts'

// Re-exported so a Tailwind config can extend the default set without pulling in
// the component barrel (`@vyui/kit`) through jiti:
//   import vyuiPreset, { createVyuiPreset, COLORS } from '@vyui/kit/tailwind'
export { COLORS, NEUTRAL } from './theme/color-constants.js'

/**
 * Extra `ui-*` state markers the kit themes use beyond the lynx preset's
 * built-in set (`open/closed/active/checked/disabled/...`). These back the
 * class-based variants (`ui-on:`, `group-ui-completed:`, etc.) that replace
 * Lynx-incompatible `data-[state=…]` attribute selectors (issue #9). Feed them
 * into the lynx preset's `uiVariants` plugin so it generates the self/group/
 * peer/parent forms:
 *
 * ```ts
 * import { createLynxPreset } from '@lynx-js/tailwind-preset'
 * import { VYUI_UI_STATES } from '@vyui/kit/tailwind'
 * const lynxPreset = createLynxPreset({
 *   lynxUIPlugins: {
 *     uiVariants: { prefixes: (d) => ({ ...d, ui: [...d.ui, ...VYUI_UI_STATES] }) },
 *   },
 * })
 * ```
 */
export const VYUI_UI_STATES = ['on', 'off', 'completed', 'highlighted', 'inactive', 'dragging']

// Theme-barrel exports that are not tailwind-variants theme configs.
const NON_THEME_EXPORTS = new Set(['icons', 'ALL_COLORS', 'COLORS', 'NEUTRAL', 'resolveColors'])

/**
 * Styled components rendered INSIDE other kit components (the `import Vy*`
 * graph in `src/components`): a consumer safelisting `components: ['button']`
 * must also get `avatar`'s classes (Button renders a leading `VyAvatar`), and
 * so on transitively. Keys/values are `@vyui/kit/theme` export names.
 */
const THEME_DEPS = {
  avatar: ['chip'],
  avatarGroup: ['avatar'],
  badge: ['avatar'],
  button: ['avatar'],
  calendar: ['alert'],
  input: ['avatar'],
  modal: ['button'],
  textarea: ['avatar'],
  toast: ['avatar', 'button'],
}

/** Expand a component list through `THEME_DEPS` to its transitive closure. */
const expandThemeDeps = (names) => {
  const seen = new Set()
  const queue = [...names]
  while (queue.length) {
    const name = queue.pop()
    if (seen.has(name)) continue
    seen.add(name)
    queue.push(...(THEME_DEPS[name] ?? []))
  }
  return seen
}

/** Add every whitespace-separated class token found in a tv class value
 * (string / array / slot-map object) to `into`. */
const collectStrings = (node, into) => {
  if (typeof node === 'string') {
    for (const cls of node.split(/\s+/)) if (cls) into.add(cls)
  }
  else if (Array.isArray(node)) {
    for (const item of node) collectStrings(item, into)
  }
  else if (node && typeof node === 'object') {
    for (const value of Object.values(node)) collectStrings(value, into)
  }
}

/**
 * Collect the EXACT set of class names every packaged theme emits for a given
 * color list, by walking the tv configs (base/slots/variants/compoundVariants
 * — `defaultVariants` holds variant NAMES, not classes). Builder themes are
 * invoked with the resolved colors, so template-literal color classes
 * (`bg-${c}-500`, `group-ui-active:text-${c}-500`, …) come out as concrete
 * strings — the classes Tailwind's static scanner cannot see.
 *
 * This replaces the previous `(bg|text|ring|border) × color × shade × variant`
 * safelist patterns, which emitted every COMBINATION (~11k rules, ~550 KB+ of
 * CSS the device style engine had to ingest) when the themes only ever
 * reference a small fraction.
 */
const collectThemeSafelist = (colors, components) => {
  const only = components ? expandThemeDeps(components) : undefined
  const classes = new Set()
  for (const [name, theme] of Object.entries(themeExports)) {
    if (NON_THEME_EXPORTS.has(name)) continue
    if (only && !only.has(name)) continue
    const config = typeof theme === 'function' ? theme(colors) : theme
    if (!config || typeof config !== 'object') continue
    collectStrings(config.base, classes)
    collectStrings(config.slots, classes)
    for (const group of Object.values(config.variants ?? {})) {
      for (const value of Object.values(group ?? {})) collectStrings(value, classes)
    }
    for (const compound of [...(config.compoundVariants ?? []), ...(config.compoundSlots ?? [])]) {
      collectStrings(compound.class, classes)
      collectStrings(compound.className, classes)
    }
  }
  return [...classes].sort()
}

const buildScale = (name, neutral, shades) =>
  Object.fromEntries([
    ...shades.map((shade) => [shade, `var(--ui-color-${name}-${shade})`]),
    // Mode-aware shorthand. `neutral` has no `--ui-neutral` (matches Nuxt UI),
    // so skip DEFAULT for it.
    ...(name === neutral ? [] : [['DEFAULT', `var(--ui-${name})`]]),
  ])

/**
 * Border-radius scale wired to `--ui-radius` (defined in `style.css`).
 * Mirrors nuxt/ui v3's ratios so every `rounded-*` utility rescales when the
 * single var is overridden. `none` and `full` keep Tailwind's defaults.
 */
const RADIUS_SCALE = {
  xs: 'calc(var(--ui-radius) * 0.5)',
  sm: 'var(--ui-radius)',
  DEFAULT: 'var(--ui-radius)',
  md: 'calc(var(--ui-radius) * 1.5)',
  lg: 'calc(var(--ui-radius) * 2)',
  xl: 'calc(var(--ui-radius) * 3)',
  '2xl': 'calc(var(--ui-radius) * 4)',
  '3xl': 'calc(var(--ui-radius) * 6)',
}

/**
 * Build the @vyui/kit preset for a given color set. Defaults to the package's
 * standard semantic colors.
 *
 * Accepts EITHER the flat preset options (`{ colors, neutral, shades }`) OR a
 * normalized config from `defineVyuiConfig` (`{ ui: { colors } }`) — pass the
 * SAME config object here and to `provideVyUI` so the generated palette and the
 * runtime `ui.colors` can't drift.
 *
 * @param {object} [options] Flat options, or a `defineVyuiConfig` result.
 * @param {string[]} [options.colors] Configurable semantic colors (no neutral).
 * @param {string}   [options.neutral] Neutral color name.
 * @param {number[]} [options.shades] Tailwind shade steps.
 * @param {string[]} [options.components] Restrict the theme safelist to these
 *   components (`@vyui/kit/theme` export names, e.g. `['button', 'tabs']`).
 *   Components they render internally are pulled in automatically
 *   (`THEME_DEPS`). Omit to safelist every packaged theme.
 * @param {object}   [options.ui] Normalized config; `ui.colors` overrides `colors`.
 * @returns {Partial<TailwindConfig>}
 */
export function createVyuiPreset(options = {}) {
  // Unwrap the normalized `{ ui }` config from defineVyuiConfig; fall back to
  // the flat `{ colors, neutral, shades }` form for direct callers.
  const src = options.ui ?? options
  const { colors = COLORS, neutral = NEUTRAL, shades = SHADES, components } = src

  // Silent "class resolves to nothing" is the worst DX here: a semantic color
  // outside the package set generates utilities but only paints if the consumer
  // also defines matching `--ui-color-<name>-*` CSS vars AND lists it in the
  // runtime `theme.colors`. Surface that at build time (dev only — this file
  // runs in Node via Tailwind's jiti loader, so `process.env` is available).
  if (process.env.NODE_ENV !== 'production') {
    const custom = colors.filter((c) => !COLORS.includes(c))
    if (custom.length > 0) {
      console.warn(
        `[vyui/tailwind] custom semantic color(s) [${custom.join(', ')}] will emit `
        + 'utilities, but only resolve if you also define matching '
        + '`--ui-color-<name>-*` CSS vars and list them in your runtime '
        + '`theme.colors` (provideVyUI / app.use). Otherwise the classes paint nothing.',
      )
    }
    // Same failure mode for a typo'd component name: the filter would silently
    // drop a real theme's classes.
    const unknown = (components ?? []).filter((c) => !(c in themeExports) || NON_THEME_EXPORTS.has(c))
    if (unknown.length > 0) {
      console.warn(
        `[vyui/tailwind] unknown component theme(s) in \`components\`: [${unknown.join(', ')}]. `
        + 'Names must match the `@vyui/kit/theme` exports (e.g. `button`, `drawer`).',
      )
    }
  }

  const allColors = [...new Set([...colors, neutral])]
  return {
    // The library flips via semantic tokens under a `.dark` class (not `dark:`
    // utilities), but pin the trigger to `class` so any `dark:` a CONSUMER
    // writes keys off the same `.dark` ancestor `useColorMode` toggles.
    darkMode: 'class',
    theme: {
      extend: {
        colors: Object.fromEntries(
          allColors.map((name) => [name, buildScale(name, neutral, shades)]),
        ),
        // Semantic tokens — role-based utilities wired to the `--ui-*` tokens in
        // `style.css`. Themes (and consumers) use these instead of raw ramp
        // classes, so they flip in dark on their own (each token holds a
        // per-mode `theme()` literal → one-hop var(), Lynx-safe). Scoped to
        // `backgroundColor` / `textColor` / `borderColor` / `divideColor` /
        // `fill` so each name only emits its own utility family.
        //   surfaces: `bg-default` (cards/fields/overlays) + `bg-muted` /
        //   `bg-elevated` / `bg-accented` fills + `bg-inverted` (neutral solid).
        backgroundColor: {
          default: 'var(--ui-bg)',
          muted: 'var(--ui-bg-muted)',
          elevated: 'var(--ui-bg-elevated)',
          accented: 'var(--ui-bg-accented)',
          inverted: 'var(--ui-bg-inverted)',
        },
        // text: `text-default` (body) → `text-highlighted` (emphasis), plus
        // `text-muted` / `text-dimmed` / `text-toned` and `text-inverted` (the
        // foreground for `bg-inverted` fills).
        textColor: {
          default: 'var(--ui-text)',
          dimmed: 'var(--ui-text-dimmed)',
          muted: 'var(--ui-text-muted)',
          toned: 'var(--ui-text-toned)',
          highlighted: 'var(--ui-text-highlighted)',
          inverted: 'var(--ui-text-inverted)',
        },
        // borders: `border-default` + `border-muted` / `border-accented` /
        // `border-inverted`. Lowercase `default` emits `border-default` (a color
        // utility); it does NOT touch the bare `border` (which stays the
        // borderWidth DEFAULT below), so existing `border` usages are unaffected.
        borderColor: {
          default: 'var(--ui-border)',
          muted: 'var(--ui-border-muted)',
          accented: 'var(--ui-border-accented)',
          inverted: 'var(--ui-border-inverted)',
        },
        // `divide-default` / `divide-muted` — dividers ride the border tokens.
        divideColor: {
          default: 'var(--ui-border)',
          muted: 'var(--ui-border-muted)',
        },
        // `fill-default` — SVG fills (e.g. the popover/select arrow) ride the
        // border token so they flip with the surface edge.
        fill: {
          default: 'var(--ui-border)',
        },
        borderRadius: RADIUS_SCALE,
        // Halve every numeric step of the borderWidth scale. The bare
        // `border` utility uses `DEFAULT`; `border-2` / `border-4` keep their
        // names but render at half-pixel widths so the whole project's stroke
        // weight reads thinner without rewriting every component. `border-0`
        // and `border-8` are left at their stock values (the former is "off",
        // the latter is a deliberate fat outline).
        borderWidth: {
          DEFAULT: '0.5px',
          2: '1px',
          4: '2px',
        },
      },
    },
    safelist: [
      // Every class the packaged themes emit for THIS color set — variant
      // prefixes (`active:`, `group-ui-*:`) and arbitrary values
      // (`shadow-[…var(--ui-color-primary-200)]`) included, since they sit in
      // the theme strings themselves. Covers a consumer who only pulls the
      // preset without scanning `@vyui/kit` sources.
      ...collectThemeSafelist(allColors, components),
      // Semantic tokens — role-based utilities (`text-muted`, `bg-elevated`,
      // `border-default`, …) kept as a pattern (not just the themes' usages)
      // so consumers can write any of them without scanning the kit. The
      // pattern over-matches (e.g. `text-elevated`) but Tailwind only emits
      // names backed by a real utility.
      {
        pattern: /(bg|text|border)-(default|muted|elevated|accented|toned|dimmed|highlighted|inverted)/,
      },
      'divide-default',
      'divide-muted',
      'fill-default',
      'text-white',
    ],
  }
}

/** Default preset (standard color set). Keeps `presets: [..., vyuiPreset]` working. */
export default createVyuiPreset()
